{{ silver_model_config('SEC_ADV_DISCLOSURE_EVENT') }}

select
    accession_number,
    event_index,
    disclosure_category,
    event_date,
    is_reported,
    description,
    parser_version,
    last_sync_run_id
from {{ source('edgartools_silver_landing', 'SEC_ADV_DISCLOSURE_EVENT') }}
qualify row_number() over (
    partition by accession_number, event_index
    order by parse_sequence desc
) = 1
  and {{ silver_not_retired('sec_adv_disclosure_event', "concat_ws('|', accession_number, event_index)") }}
